import csv
import os
import tempfile

def export_waitlist(records: list[dict[str, object]], destination: str) -> int:
    waiting = []
    for record in records:
        priority = record['priority']
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError('priority must be an integer')
        if record['status'] == 'waiting':
            waiting.append(record)
    waiting.sort(key=lambda record: (record['priority'], record['requested_date'], record['patient']))
    parent = os.path.dirname(os.path.abspath(destination))
    descriptor, temporary = tempfile.mkstemp(dir=parent, prefix='.waitlist-')
    try:
        with os.fdopen(descriptor, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['patient', 'specialty', 'priority', 'requested_date'])
            for record in waiting:
                writer.writerow([record['patient'], record['specialty'], record['priority'], record['requested_date']])
        os.replace(temporary, destination)
    except Exception:
        if os.path.exists(temporary):
            os.unlink(temporary)
        raise
    return len(waiting)

