import hashlib
import hmac
import json

def verify_docket_webhook(payload: str, signature_header: str, secret: str) -> bool:
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        return False
    if not isinstance(data, dict):
        return False
    if data.get('event') != 'docket.updated':
        return False
    if not isinstance(data.get('docket_id'), str) or not data['docket_id']:
        return False
    if not signature_header.startswith('sha256='):
        return False
    supplied = signature_header[len('sha256='):]
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(supplied, expected)

