import os
from pathlib import Path

def save_consultation_summary(base_dir: str, relative_name: str, summary: str) -> str:
    if not relative_name or not relative_name.lower().endswith('.txt'):
        raise ValueError('relative_name must be a non-empty .txt path')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('relative_name is not within base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(summary, encoding='utf-8')
    return str(target)

import os
import subprocess

def rank_matchmaking_queue(path: str) -> list[tuple[str, int]]:
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    result = subprocess.run(['sort', '-t,', '-k2,2nr', '-k1,1', path], check=True, capture_output=True, text=True)
    records = []
    for line in result.stdout.splitlines():
        if not line:
            continue
        parts = line.split(',')
        if len(parts) != 2:
            raise ValueError('invalid queue record')
        try:
            records.append((parts[0], int(parts[1])))
        except ValueError as exc:
            raise ValueError('invalid queue record') from exc
    return records

