def export_yield_predictions(predictions: list[tuple[str, float]], destination: str) -> int:
    for crop, value in predictions:
        if value < 0:
            raise ValueError('yield values must not be negative')
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary_path = tempfile.mkstemp(prefix='.yield-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as output:
            writer = csv.writer(output, lineterminator='\n')
            writer.writerow(['crop', 'predicted_yield'])
            for crop, value in sorted(predictions, key=lambda item: item[0]):
                writer.writerow([crop, f'{value:.2f}'])
        os.replace(temporary_path, destination)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise
    return len(predictions)

