import secrets

def generate_beneficiary_invite_code(beneficiary_name: str) -> str:
    if not isinstance(beneficiary_name, str):
        raise ValueError('beneficiary name must be a string')
    letters = [character for character in beneficiary_name if character.isalpha()]
    if not letters:
        raise ValueError('beneficiary name must contain a letter')
    prefix = ''.join(letters[:2]).upper()
    if len(prefix) == 1:
        prefix += 'X'
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(8)))
    return f'{prefix}-{code}'

