def parse_maintenance_records(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'maintenance':
        raise ValueError('invalid root')
    fields = ('aircraft', 'date', 'technician', 'status')
    records = []
    for element in root.findall('record'):
        if any((field not in element.attrib for field in fields)):
            raise ValueError('missing record attribute')
        if element.attrib['status'] not in {'open', 'closed'}:
            raise ValueError('invalid status')
        records.append({field: element.attrib[field] for field in fields})
    records.sort(key=lambda record: record['date'], reverse=True)
