import xml.sax.handler

class _RecordHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.root = None
        self.in_record = False
        self.records = []
        self.fields = ('aircraft', 'date', 'technician', 'status')

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'record':
