import hashlib
import hmac
import secrets

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and len(pin) == 4 and all(('0' <= ch <= '9' for ch in pin))

def create_driver_pin_record(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('pin must contain exactly four ASCII digits')
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode('ascii'), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_driver_pin(pin: str, record: str) -> bool:
    if not _valid_pin(pin) or not isinstance(record, str):
        return False
    try:
        salt_text, digest_text = record.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('ascii'), salt, 100000)
    return hmac.compare_digest(actual, expected)

