import xml.sax.handler

class _BomHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.components = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'component':
            component_name = attrs.get('name')
            quantity_text = attrs.get('quantity')
            if not component_name:
                raise ValueError('invalid component name')
            try:
                quantity = int(quantity_text)
            except (TypeError, ValueError) as exc:
                raise ValueError('invalid quantity') from exc
            if quantity <= 0:
                raise ValueError('invalid quantity')
            self.components.append((component_name, quantity))

def parse_bom(xml_text: str) -> list[tuple[str, int]]:
    handler = _BomHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except ValueError:
        raise
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'bom':
        raise ValueError('wrong root element')
    return sorted(handler.components, key=lambda item: item[0])

