def make_signature(payload, secret):
    return hmac.new(secret, payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_returns_low_stock_items_sorted_by_sku():
    payload = json.dumps({
        "items": [
            {"sku": "Z-2", "quantity": 1, "reorder_level": 3},
            {"sku": "A-1", "quantity": 2, "reorder_level": 4},
            {"sku": "M-5", "quantity": 8, "reorder_level": 4},
        ]
    }, separators=(",", ":"))
    secret = b"warehouse-key"
    result = get_replenishment_items(payload, make_signature(payload, secret), secret)
    assert result == [
        {"sku": "A-1", "quantity": 2, "reorder_level": 4},
        {"sku": "Z-2", "quantity": 1, "reorder_level": 3},
    ]


def test_equal_quantity_is_not_replenished_and_empty_result_is_allowed():
