import hashlib
import hmac
import json

def parse_signed_receivable(payload: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = signature[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('invalid payload')
    if not isinstance(value.get('invoice_id'), str) or not value['invoice_id']:
        raise ValueError('invalid invoice')
    if not isinstance(value.get('customer'), str) or not value['customer']:
