import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(child, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, child in zip(node.ops, node.comparators):
            right = _evaluate(child, values)
            result = {ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right, ast.Eq: left == right, ast.NotEq: left != right}[type(op)]
            if not result:
                return False
            left = right
        return True
    raise ValueError('unsupported expression')

