def parse_donations(xml_text: str) -> list[tuple[str, float]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'donations':
        raise ValueError('unexpected root')
    result = []
    for item in root:
        if item.tag != 'donation':
            raise ValueError('unexpected element')
        donor_node = item.find('donor')
        amount_node = item.find('amount')
        if donor_node is None or amount_node is None:
            raise ValueError('missing donation field')
        donor = (donor_node.text or '').strip()
        if not donor:
            raise ValueError('empty donor')
        try:
            amount = float((amount_node.text or '').strip())
        except ValueError as exc:
            raise ValueError('invalid amount') from exc
        if amount <= 0:
            raise ValueError('amount must be positive')
        result.append((donor, amount))
    return sorted(result, key=lambda entry: (-entry[1], entry[0]))

