class _DonationHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.items = []
        self.current = None
        self.field = None
        self.parts = []

    def startElement(self, name, attrs):
        if name == 'donation':
            self.current = {}
        elif name in ('donor', 'amount') and self.current is not None:
            self.field = name
            self.parts = []

