def create_asset_key_record(key: str) -> str:
    if not key:
        raise ValueError('key must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', key.encode('utf-8'), salt, _ITERATIONS)
