        return False
    try:
        salt_text, digest_text = record.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', key.encode('utf-8'), salt, _ITERATIONS)
    return hmac.compare_digest(actual, expected)

