        elif 'bad' in text or 'poor' in text:
            category = 'negative'
        else:
            category = 'neutral'
        classifications.append(category)
        counts[category] += 1
    payload = ','.join(classifications).encode()
    signature = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return {'total': len(feedback), **counts, 'signature': signature}

