import xml.sax.handler

class _PointsHandler(xml.sax.handler.ContentHandler):

    def __init__(self, member_id: str) -> None:
        super().__init__()
        self.member_id = member_id
        self.current_member = None
        self.total = 0

    def startElement(self, name, attrs):
        if name == 'member':
            self.current_member = attrs.get('id')
        elif name == 'transaction' and self.current_member == self.member_id:
            if attrs.get('status') == 'approved':
                self.total += int(attrs.get('points', '0'))

    def endElement(self, name):
        if name == 'member':
            self.current_member = None

