import xml.etree.ElementTree as ET

def extract_mentions(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'report':
        raise ValueError('invalid root')
    result = []
    for mention in root:
        if mention.tag != 'mention' or 'outlet' not in mention.attrib:
            raise ValueError('invalid mention')
        values = {}
        for child in mention:
            if child.tag in ('title', 'date') and child.tag not in values:
                values[child.tag] = (child.text or '').strip()
        if 'title' not in values or 'date' not in values:
            raise ValueError('invalid mention')
        result.append({'outlet': mention.attrib['outlet'].strip(), **values})
    result.sort(key=lambda item: item['date'], reverse=True)
    return result

