from xml.sax.handler import ContentHandler, feature_external_ges

class _MentionHandler(ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.current = None
        self.field = None
        self.text = []
        self.items = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name == 'mention':
            if 'outlet' not in attrs:
                raise ValueError('invalid mention')
            self.current = {'outlet': attrs['outlet'].strip()}
        elif self.current is not None and name in ('title', 'date'):
            self.field = name
            self.text = []

    def characters(self, content):
        if self.field is not None:
            self.text.append(content)

    def endElement(self, name):
        if self.current is not None and name == self.field:
            self.current[name] = ''.join(self.text).strip()
            self.field = None
        elif name == 'mention' and self.current is not None:
            if 'title' not in self.current or 'date' not in self.current:
                raise ValueError('invalid mention')
            self.items.append(self.current)
            self.current = None

def extract_mentions(xml_text: str) -> list[dict[str, str]]:
    handler = _MentionHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except (xml.sax.SAXException, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'report':
        raise ValueError('invalid root')
    handler.items.sort(key=lambda item: item['date'], reverse=True)
    return handler.items

