import secrets

def _valid_pin(pin: str) -> bool:
    return isinstance(pin, str) and 4 <= len(pin) <= 8 and pin.isdigit()

def hash_pin(pin: str) -> str:
    if not _valid_pin(pin):
        raise ValueError('PIN must contain 4 to 8 digits')
    iterations = 100000
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_pin(pin: str, stored: str) -> bool:
    if not _valid_pin(pin) or not isinstance(stored, str):
        return False
    try:
        iteration_text, salt_text, digest_text = stored.split('$')
        iterations = int(iteration_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

