import xml.etree.ElementTree as ET

def find_polling_places(xml_text: str, district: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'polling_places':
        raise ValueError('unexpected root element')
    results = []
    for place in root.findall('place'):
        address = place.findtext('address', default='').strip()
        item = {'id': place.attrib['id'], 'name': place.attrib['name'], 'address': address}
        if place.attrib['district'] == district:
            results.append(item)
    results.sort(key=lambda item: item['id'])
    return results

