def mark_spot_aired(requester: dict[str, object], campaign: dict[str, object], spot_id: str) -> dict[str, object]:
    same_tenant = requester.get('tenant_id') == campaign.get('tenant_id')
    is_owner = requester.get('id') == campaign.get('owner_id')
    is_manager = requester.get('role') == 'traffic_manager' and same_tenant
