import json
import re

def verify_shipment_update(payload: str, signature: str, shared_key: str) -> dict:
    if not re.fullmatch('sha256=[0-9a-f]{64}', signature):
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(shared_key.encode(), payload.encode(), hashlib.sha256).hexdigest()
