def search_kb(entries: list[dict], rule: str, limit: int) -> list[dict]:
    import ast
    import operator
    if limit < 0:
        raise ValueError('limit must not be negative')
    tree = ast.parse(rule, mode='eval')
    allowed = {'title', 'text', 'score', 'year', 'views'}
    functions = {'min', 'max', 'round'}
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id not in allowed | functions:
            raise NameError(node.id)

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.Not):
                return not value
            raise ValueError('unsupported expression')
        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                result = True
                for item in node.values:
                    result = evaluate(item, values)
                    if not result:
                        return result
                return result
            for item in node.values:
                result = evaluate(item, values)
                if result:
                    return result
            return result
        if isinstance(node, ast.Compare):
            ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            left = evaluate(node.left, values)
            for op, item in zip(node.ops, node.comparators):
                if type(op) not in ops:
                    raise ValueError('unsupported expression')
                right = evaluate(item, values)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (not node.keywords) and (node.func.id in functions):
            args = [evaluate(item, values) for item in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('unsupported expression')
    matched = []
    for entry in entries:
        values = {name: entry[name] for name in allowed}
        if evaluate(tree.body, values):
            matched.append(entry)
    matched.sort(key=lambda item: (-item['score'], item['title']))
    return matched[:limit]

