def parse_seed_inventory(xml_text: str) -> list[tuple[str, int]]:
    root = ET.fromstring(xml_text)
    records = []
    for element in root.findall('seed'):
        variety = element.get('variety')
        quantity_text = element.get('quantity')
        if variety is None or quantity_text is None:
