import subprocess

def schedule_ports(used_ports_file: str, start_port: int, count: int) -> list[int]:
    if not 1 <= start_port <= 65535 or count < 1:
        raise ValueError('invalid port range')
    result = subprocess.run(['sort', '-n', used_ports_file], check=True, capture_output=True, text=True)
    used = set()
    for line in result.stdout.splitlines():
        try:
            port = int(line.strip())
        except ValueError:
            continue
        if 1 <= port <= 65535:
            used.add(port)
    available = [port for port in range(start_port, 65536) if port not in used]
    if len(available) < count:
        raise ValueError('not enough ports')
    return available[:count]

