def save_registration_document(base_dir: str, relative_name: str, content: str) -> str:
    if not relative_name or not relative_name.lower().endswith('.pdf'):
        raise ValueError('invalid document name')
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('document must be within base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return os.fspath(target)

