import ast
import operator

def _evaluate(node, context):
    if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in context:
            raise ValueError('unknown variable')
        return context[node.id]
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, context)
        right = _evaluate(node.right, context)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](left, right)
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, context)
        ops = {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}
        if type(node.op) not in ops:
            raise ValueError('invalid expression')
        return ops[type(node.op)](value)
    if isinstance(node, ast.BoolOp):
        values = [_evaluate(node.values[0], context)]
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not values[-1]):
                return values[-1]
            if isinstance(node.op, ast.Or) and values[-1]:
                return values[-1]
            values.append(_evaluate(item, context))
        return values[-1]
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, context)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, context)
            ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            if type(op) not in ops:
                raise ValueError('invalid expression')
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    raise ValueError('invalid expression')

def evaluate_flags(flags: list[tuple[str, str]], context: dict[str, int | float | bool]) -> list[str]:
    result = []
    for name, expression in flags:
        try:
            tree = ast.parse(expression, mode='eval')
            if _evaluate(tree.body, context):
                result.append(name)
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError('invalid expression') from exc
    return result

