import os

def hash_cost_access_key(secret: str) -> str:
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
