def list_plan_versions(directory: str, prefix: str) -> list[str]:
    if not prefix or not re.fullmatch('[A-Za-z0-9_-]+', prefix):
        raise ValueError('invalid prefix')
    try:
        result = subprocess.run(['ls', '-1', directory], check=True, capture_output=True, text=True)
    except (subprocess.CalledProcessError, OSError) as exc:
        raise ValueError('unable to list directory') from exc
    pattern = re.compile(f'^{re.escape(prefix)}-v(\\d+)\\.plan$')
    versions = []
    for name in result.stdout.splitlines():
        match = pattern.fullmatch(name)
        if match:
            versions.append((int(match.group(1)), name))
    versions.sort(key=lambda item: item[0])
    return [name for _, name in versions]

