import xml.etree.ElementTree as ET

def parse_fraud_case(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'case' or not root.get('id'):
        raise ValueError('missing case id')
    subject_node = root.find('subject')
    alerts_node = root.find('alerts')
    if subject_node is None or alerts_node is None:
        raise ValueError('missing required element')
    alerts = []
    for node in alerts_node.findall('alert'):
        if not node.get('id') or not node.get('severity'):
            raise ValueError('missing alert attribute')
        alerts.append({'id': node.get('id'), 'severity': node.get('severity'), 'summary': (node.text or '').strip()})
    ranks = {'high': 0, 'medium': 1, 'low': 2}
    alerts.sort(key=lambda item: (ranks.get(item['severity'], 3), item['id']))
    return {'case_id': root.get('id'), 'subject': (subject_node.text or '').strip(), 'alerts': alerts}

