        self.case_id = None
        self.subject = None
        self.alerts = []
        self.current = None
        self.text = []
        self.alerts_seen = False

    def startElement(self, name, attrs):
        self.path.append(name)
        if name == 'case':
            self.case_id = attrs.get('id')
        elif name == 'alerts':
            self.alerts_seen = True
        elif name == 'alert':
            self.current = {'id': attrs.get('id'), 'severity': attrs.get('severity')}
            self.text = []
        elif name == 'subject':
            self.text = []

    def characters(self, content):
        if self.path and (self.path[-1] == 'subject' or self.path[-1] == 'alert'):
            self.text.append(content)

    def endElement(self, name):
