        elif name == 'alert':
            if self.current is None or not self.current['id'] or (not self.current['severity']):
                raise ValueError('missing alert attribute')
            self.current['summary'] = ''.join(self.text).strip()
            self.alerts.append(self.current)
            self.current = None
