def course_codes_from_roster(path: str) -> list[str]:
    if not path:
        raise ValueError('path must not be empty')
    result = subprocess.run(f'''awk -F, 'index($0, ",") {{ print $1 }}' "{path}"''', shell=True, check=True, capture_output=True, text=True)
    codes = set()
    for line in result.stdout.splitlines():
        code = line.strip()
        if code:
            codes.add(code)
    return sorted(codes)

