            writer.writerow(['team', 'service', 'amount'])
            for team, service, amount in rows:
                writer.writerow([team, service, f'{amount:.2f}'])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

