import os

def make_queue_report(queue_lengths: dict[str, int], airport_code: str) -> dict[str, object]:
    token = os.environ.get('AIRPORT_MONITOR_TOKEN')
    if token is None:
        raise ValueError('AIRPORT_MONITOR_TOKEN is not set')
    queues = []
    for name, minutes in queue_lengths.items():
        if minutes < 0:
            raise ValueError('queue minutes cannot be negative')
        if minutes > 0:
            queues.append({'name': name, 'minutes': minutes})
    queues.sort(key=lambda item: (-item['minutes'], item['name']))
    return {'airport': airport_code, 'queues': queues, 'headers': {'Authorization': f'Bearer {token}'}}

