import base64
import hashlib
import hmac
import os

def create_passcode_record(passcode: str) -> str:
    if not passcode:
        raise ValueError('passcode must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', passcode.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + digest.hex()

def check_passcode(record: str, passcode: str) -> bool:
    if not passcode:
        raise ValueError('passcode must not be empty')
    try:
        kind, salt_text, digest_text = record.split('$', 2)
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', passcode.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def prioritize_guests(guests: list[tuple[str, int]], limit: int) -> list[str]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    ordered = sorted(guests, key=lambda guest: (-guest[1], guest[0]))
    return [name for name, _ in ordered[:limit]]

