    if not isinstance(participant_number, int) or isinstance(participant_number, bool) or (not 1 <= participant_number <= 999999):
        raise ValueError('invalid participant number')
    alphabet = string.ascii_uppercase + string.digits
    suffix = ''.join((random.choice(alphabet) for _ in range(10)))
    return f'{site_code.upper()}-{participant_number:06d}-{suffix}'

