import os
import tempfile

def export_proctoring_events(events: list[dict[str, object]]) -> str:
    rows = []
    for event in events:
        if any((field not in event for field in ('timestamp', 'candidate', 'event', 'severity'))):
            raise ValueError('missing field')
        severity = event['severity']
        if severity not in {'info', 'warning', 'critical'}:
            raise ValueError('invalid severity')
        if severity != 'info':
            rows.append(event)
    rows.sort(key=lambda item: str(item['timestamp']))
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['timestamp', 'candidate', 'event', 'severity'])
            for event in rows:
                writer.writerow([event[field] for field in ('timestamp', 'candidate', 'event', 'severity')])
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

