import xml.etree.ElementTree as ET

def extract_invoice(xml_text: str) -> dict:
    root = ET.fromstring(xml_text)
    values = {}
    for name in ('invoice_id', 'vendor', 'amount', 'approved'):
        element = root.find(name)
        values[name] = (element.text or '').strip()
    amount = float(values['amount'])
    if amount < 0:
        raise ValueError('amount must not be negative')
    approval = values['approved'].lower()
    if approval not in ('true', 'false'):
        raise ValueError('approved must be true or false')
    return {'invoice_id': values['invoice_id'], 'vendor': values['vendor'], 'amount': amount, 'approved': approval == 'true'}

