def filter_access_requests(requests: list[dict], rule: str) -> list[dict]:
    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in values:
            return values[node.id]
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not evaluate(node.operand, values)
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            operations = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            return operations[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            operations = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                if type(op) not in operations or not operations[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError('unsupported rule')
    result = []
    for request in requests:
