import ast

def _eval(node, names):
    if isinstance(node, ast.Expression):
        return _eval(node.body, names)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name) and node.id in names:
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _eval(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_eval(node.left, names), _eval(node.right, names))
        return a + b if isinstance(node.op, ast.Add) else a - b if isinstance(node.op, ast.Sub) else a * b if isinstance(node.op, ast.Mult) else a / b
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _eval(node.values[0], names)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _eval(child, names)
        return value
    if isinstance(node, ast.Compare):
        left = _eval(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            right = _eval(part, names)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
                raise ValueError()
            good = left < right if isinstance(op, ast.Lt) else left <= right if isinstance(op, ast.LtE) else left > right if isinstance(op, ast.Gt) else left >= right if isinstance(op, ast.GtE) else left == right if isinstance(op, ast.Eq) else left != right
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_eval(a, names) for a in node.args]
        if node.func.id == 'round' and len(args) in (1, 2):
            return round(*args)
        if node.func.id in ('min', 'max') and len(args) >= 2:
            return min(args) if node.func.id == 'min' else max(args)
    raise ValueError()

def process_fuel_payments(payments: list[dict[str, object]], rule: str) -> dict[str, object]:
    try:
        tree = ast.parse(rule, mode='eval')
        accepted = [p for p in payments if _eval(tree, {'amount': p['amount'], 'liters': p['liters'], 'price': p['price']})]
    except Exception as exc:
        raise ValueError() from exc
    return {'accepted_ids': [p['id'] for p in accepted], 'total_amount': round(sum((p['amount'] for p in accepted)), 2), 'total_liters': round(sum((p['liters'] for p in accepted)), 2)}

