import os

def create_risk_profile(scores: list[int], client_id: str) -> dict[str, str]:
    if not scores or any((type(score) is not int or score < 1 or score > 5 for score in scores)):
        raise ValueError('scores must be non-empty integers from 1 through 5')
    key = os.environ.get('ROBO_ADVISOR_SIGNING_KEY')
    if key is None:
        raise RuntimeError('ROBO_ADVISOR_SIGNING_KEY is not set')
    average = sum(scores) / len(scores)
    if average <= 2.0:
        category = 'conservative'
    elif average <= 3.5:
        category = 'balanced'
    else:
        category = 'growth'
    average_text = f'{average:.2f}'
    unsigned = f'{client_id}|{category}|{average_text}'
    signature = hmac.new(key.encode(), unsigned.encode(), hashlib.sha256).hexdigest()
    return {'client_id': client_id, 'category': category, 'average': average_text, 'signature': signature}

