import xml.etree.ElementTree as ET

def parse_assistance_requests(xml_text: str) -> list[dict[str, str]]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    result = []
    for node in root.findall('request'):
        request_id = node.get('id')
        values = {child.tag: (child.text or '').strip() for child in node}
        if request_id is None or any((name not in values for name in ('vehicle', 'location', 'service'))):
            raise ValueError('incomplete request')
        result.append({'id': request_id, 'vehicle': values['vehicle'], 'location': values['location'], 'service': values['service']})
    return sorted(result, key=lambda item: item['id'])

