import io
import xml.sax
import xml.sax.handler

class _RequestHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        self.requests = []
        self.current = None
        self.field = None
        self.parts = []

    def startElement(self, name, attrs):
        if name == 'request':
            self.current = {'id': attrs.get('id')}
        elif self.current is not None and name in ('vehicle', 'location', 'service'):
            self.field = name
            self.parts = []

    def characters(self, content):
        if self.field is not None:
            self.parts.append(content)

    def endElement(self, name):
        if self.current is not None and name in ('vehicle', 'location', 'service'):
            self.current[name] = ''.join(self.parts).strip()
            self.field = None
            self.parts = []
        elif name == 'request':
            self.requests.append(self.current)
            self.current = None

def parse_assistance_requests(xml_text: str) -> list[dict[str, str]]:
    handler = _RequestHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except xml.sax.SAXException as exc:
        raise ValueError('invalid XML') from exc
    result = []
    for item in handler.requests:
        if item['id'] is None or any((name not in item for name in ('vehicle', 'location', 'service'))):
            raise ValueError('incomplete request')
        result.append(item)
    return sorted(result, key=lambda item: item['id'])

