def cancel_pickup(requester: dict, pickups: list[dict], pickup_id: str) -> list[dict]:
    selected = None
    for pickup in pickups:
        if pickup['id'] == pickup_id:
            selected = pickup
            break
    if selected is None:
        raise KeyError(pickup_id)
    if selected['status'] != 'scheduled':
        raise ValueError('pickup is not scheduled')
    if selected['resident_id'] != requester['id'] and 'operations' not in requester.get('roles', []):
        raise PermissionError('requester cannot cancel this pickup')
    result = [pickup.copy() for pickup in pickups]
    for pickup in result:
        if pickup['id'] == pickup_id:
            pickup['status'] = 'cancelled'
    return sorted(result, key=lambda pickup: (pickup['pickup_date'], pickup['id']))

