def parse_flight_plan(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'flightPlan':
        raise ValueError('invalid root element')
    values = {}
    for name in ('callsign', 'departure', 'destination', 'altitude', 'route'):
        element = root.find(name)
        if element is None or element.text is None:
            raise ValueError('missing flight plan field')
        values[name] = element.text.strip()
    try:
        altitude = int(values['altitude'])
    except ValueError as exc:
        raise ValueError('invalid altitude') from exc
    if altitude <= 0:
        raise ValueError('invalid altitude')
    return {'callsign': values['callsign'], 'departure': values['departure'], 'destination': values['destination'], 'altitude': altitude, 'route': values['route'].split()}

